/**
 * 思而行 · 第三方组件示例：每日一句（Daily Quote）
 * 演示：自带数据表、接口、前端页面与样式，可导出分享给他人。
 */
'use strict';
let db, nowISO, sendJSON, readBody;
module.exports = {
  id: 'dailyquote', name: '每日一句', icon: '💡', kind: 'feature', scope: 'extra',
  desc: '每天显示一句与目标相关的鼓励语，可自己添加与置顶（第三方组件示例）',
  order: 40, version: '1.0.0', author: '示例作者', goalToggle: true, defaultEnabled: false,
  client: '/plugins/dailyquote.js',
  init(ctx) {
    ({ db, nowISO, sendJSON, readBody } = ctx);
    db.exec("CREATE TABLE IF NOT EXISTS dq_quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL DEFAULT 0, text TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);");
  },
  onGoalDelete(goalId, ctx) { ctx.db.prepare('DELETE FROM dq_quotes WHERE goal_id = ?').run(goalId); },
  exportData(ctx) { return { quotes: ctx.db.prepare('SELECT * FROM dq_quotes').all() }; },
  importData(data, ctx) { for (const x of ((data && data.quotes) || [])) ctx.db.prepare('INSERT OR REPLACE INTO dq_quotes (id,goal_id,text,created_at) VALUES (?,?,?,?)').run(x.id, x.goal_id, x.text, x.created_at); },
  clearAll(ctx) { ctx.db.exec('DELETE FROM dq_quotes;'); },
  api: [
    { method: 'GET', pattern: /^\/api\/goals\/(\d+)\/quotes$/, handler: async (req, res, u, ctx) => {
        const gid = Number(u.pathname.match(/\/goals\/(\d+)\//)[1]);
        if (!ctx.db.prepare('SELECT id FROM dq_quotes WHERE goal_id = ? LIMIT 1').get(gid)) {
          ctx.db.prepare('INSERT INTO dq_quotes (goal_id, text, created_at) VALUES (?,?,?)').run(gid, '先完成能完成的那一小步，路就出来了。', ctx.nowISO());
        }
        return ctx.sendJSON(res, 200, { quotes: ctx.db.prepare('SELECT * FROM dq_quotes WHERE goal_id = ? ORDER BY id DESC').all(gid) });
      } },
    { method: 'POST', pattern: /^\/api\/goals\/(\d+)\/quotes$/, handler: async (req, res, u, ctx) => {
        const gid = Number(u.pathname.match(/\/goals\/(\d+)\//)[1]);
        const body = await ctx.readBody(req);
        ctx.db.prepare('INSERT INTO dq_quotes (goal_id, text, created_at) VALUES (?,?,?)').run(gid, String(body.text || '').slice(0, 500), ctx.nowISO());
        return ctx.sendJSON(res, 201, { ok: true });
      } }
  ]
};

