/* 思而行 · 第三方组件示例：每日一句（前端） */
'use strict';
(function () {
  const { api, esc, toast, state } = SiErXing;
  async function renderQuotePage() {
    const goal = state.goal;
    const { quotes } = await api('/api/goals/' + goal.id + '/quotes');
    SiErXing.app.innerHTML = `
      <div class="page">
        <div class="pageHead"><a class="back" href="#/g/${goal.id}">← 返回目标</a>
          <h2 class="title" style="margin-left:10px;">💡 每日一句</h2></div>
        <div class="sec">
          <div class="dqBox">${quotes.length ? esc(quotes[0].text) : '还没有句子'}</div>
          <div class="field" style="margin-top:12px;">
            <textarea id="dqText" placeholder="写一句给自己的话…"></textarea>
            <div class="toolbarRow" style="margin-top:8px;"><button class="btn primary" id="dqAdd">添加</button></div>
          </div>
          <div class="dqList">${quotes.map(q => `<div class="dqItem">${esc(q.text)}</div>`).join('')}</div>
        </div>
      </div>`;
    document.getElementById('dqAdd').addEventListener('click', async () => {
      const t = (document.getElementById('dqText').value || '').trim();
      if (!t) return toast('写点什么吧');
      await api('/api/goals/' + goal.id + '/quotes', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: t }) });
      toast('已添加');
      renderQuotePage();
    });
  }
  SiErXing.registerPlugin({
    id: 'dailyquote',
    goalEntry: { label: '每日一句', icon: '💡', order: 40, hash: gid => '#/g/' + gid + '/quotes', show: goal => SiErXing.pluginEnabled(goal, 'dailyquote') },
    routes: [{ match: h => h.match(/^#\/g\/(\d+)\/quotes$/), render: async m => { await SiErXing.loadGoal(Number(m[1])); await renderQuotePage(); } }]
  });
})();

